29 x7gt│export function records(text: string): Chunk[] | undefined {
30 xkyd│  const rows = lines(text);
31 xz4v│  const opens = new Map<number, number>();
32 xkcs│  for (const row of rows) {
33 x84i│    const m = /^(\s*)[{[]\s*$/.exec(row);
34 xiyb│    if (m) opens.set(m[1].length, (opens.get(m[1].length) ?? 0) + 1);
35 xyeg│  }
36 xhq8│  const depth = [...opens].filter(([, n]) => n >= 2).map(([d]) => d).sort((a, b) => a - b)[0];
37 xg9r│  if (depth === undefined) return undefined;
38 xjm9│  const indent = "^" + " ".repeat(depth);
39 xu95│  const opener = new RegExp(indent + "[{[]\\s*$"), closer = new RegExp(indent + "[}\\]],?\\s*$");
40 xi58│  const chunks: Chunk[] = [];
41 xsyg│  let current = "";
42 xc3b│  const flush = () => {
43 xvnc│    if (!current) return;
44 xdb9│    const key = current.split("\n").map(row => row.trim()).find(row => row && !/^[{}[\],]+$/.test(row));
45 xw86│    if (!key && chunks.length) { chunks[chunks.length - 1].text += current; current = ""; return; }
46 xagj│    const parts = lexical(current);
47 xwm4│    for (const part of parts) chunks.push({ ...part, label: (parts.length > 1 ? key + " · " + part.label : key ?? "record").slice(0, 180) });
48 xhzj│    current = "";
49 x8yr│  };
50 xyuh│  for (const row of rows) {
51 x9sz│    if (opener.test(row)) flush();
52 xm5x│    current += row;
53 xsvp│    if (closer.test(row)) flush();
54 x3id│  }
55 xi7q│  flush();
56 xsya│  return chunks;
57 x9wp│}
